mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Eval_Report er on er.Sec_Id=sec.Sec_Id where er.Er_Id=#{erId}

select sec.Sec_Name as secName, case when pre.P_Name is null then sp.P_Name else pre.P_Name end as pName, case when pre.P_Category is null then sp.p_Category else pre.P_Category end as pCategory, case when pre.P_Build_Model is null then sp.P_Build_Model else pre.P_Build_Model end as pBuildModel, case when sd.D_Name is null then sp.D_Name else sd.D_Name end as pCompetentDepartmentName, mn.*, case when mn.P_Id is null then sp.P_Id else mn.P_Id end as pId from Sec_Eval_Report mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join pre_project pre on pre.P_Id = mn.P_Id left join SYS_Department sd on pre.P_Competent_Department = sd.D_Id left join Sec_Bidding_Plan sbp on sbp.Bp_Id=sec.Bp_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = mn.Sec_Id
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Er_Create_Time desc

mapper.sql:
${authSql}

    and sbp.is_new = 1


    
        
            and (
            (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) is null
            or
            (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) = ''
            )
        
        
            and (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) in
            
                #{pName}
            
        
    


    
        
            and (sec.sec_name is null or sec.sec_name = '')
        
        
            and sec.sec_name in
            
                #{secName}
            
        
    


    
        
            and (
            (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) is null
            or
            (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) = ''
            )
        
        
            and (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) in
            
                #{pCategory}
            
        
    


    
        
            and (mn.Er_Create_Uname is null or mn.Er_Create_Uname = '')
        
        
            and mn.Er_Create_Uname in
            
                #{createUname}
            
        
    


    
        
            and (mn.Er_State is null or mn.Er_State = '')
        
        
            and mn.Er_State in
            
                #{state}
            
        
    


    


    and (case when pre.P_Id is null then sp.P_Id else pre.P_Id end) = #{params.pId}


    and sec.Sec_Name like concat('%',#{params.secName},'%')


    and mn.Sec_Id = #{params.secId}
